#!/usr/bin/env python3
"""test_calc.py — E09Q3 单元测试套件(6 用例,含预期负例 1 个与 strict 修复位 1 个)"""
import unittest
from calc import divide, parse_int_list


def parse_int_list_strict(s: str) -> list[int]:
    """严格版:非数字 token 立刻抛 ValueError(供 test_6 验证修复位)。"""
    out = []
    for tok in s.split():
        try:
            out.append(int(tok))
        except ValueError:
            raise ValueError(f"parse_int_list_strict: invalid token {tok!r}")
    return out


class TestCalc(unittest.TestCase):
    def test_divide_normal(self):
        self.assertEqual(divide(10, 2), 5.0)

    def test_divide_by_zero(self):
        with self.assertRaises(ValueError):
            divide(1, 0)

    def test_parse_int_list_normal(self):
        self.assertEqual(parse_int_list("1 2 3"), [1, 2, 3])

    def test_parse_int_list_empty(self):
        self.assertEqual(parse_int_list(""), [])

    def test_parse_int_list_with_invalid_token_buggy(self):
        # 预期负例:buggy 版 parse_int_list 会静默丢弃 'x'
        self.assertEqual(parse_int_list("1 2 x"), [1, 2])

    def test_parse_int_list_with_invalid_strict(self):
        # strict 版必须抛 ValueError
        with self.assertRaises(ValueError):
            parse_int_list_strict("1 2 x")


if __name__ == "__main__":
    unittest.main(verbosity=2)

#!/usr/bin/env python3
"""calc.py — E09Q1 被测模块:divide + parse_int_list(含静默丢弃 bug)。"""


def divide(a, b):
    """b=0 抛 ValueError,否则返回 a/b。"""
    if b == 0:
        raise ValueError("DIVIDE_BY_ZERO_RAISED")
    return a / b


def parse_int_list(s: str) -> list[int]:
    """把空白分隔的 token 解析成 int 列表。

    【故意埋的 bug】遇到非数字 token 时不抛错,而是悄悄丢掉(过滤掉)。
    修复版应在 strict=True 或单独函数里立刻 raise ValueError。
    """
    out = []
    for tok in s.split():
        try:
            out.append(int(tok))
        except ValueError:
            pass  # 静默丢弃非数字 token(故意埋)
    return out


if __name__ == "__main__":
    # self-test demo
    try:
        divide(1, 0)
    except ValueError as e:
        print(f"divide(1,0) -> RAISED: {e}")

    parsed = parse_int_list("1 2 x")
    print(f"parsed={parsed}")
    if 1 in parsed and 2 in parsed and "x" not in parsed:
        print("bug_x_not_filtered (parse_int_list silently discarded non-numeric token)")
